/**
 * Finnova M-RAL - Central Module Registry Loader
 * 
 * ============================================================================
 * ARCHITECTURE NOTICE: THIS FILE IS FILLED ONCE FOR THE ENTIRE PLATFORM.
 * DO NOT EDIT THIS FILE PER FEATURE OR WHEN DEVELOPING INDIVIDUAL MODULES!
 * ============================================================================
 * 
 * To build or modify a module, work strictly inside your own folder:
 *   modules/<module-id>/
 * 
 * Each module self-registers by invoking `FinnovaNavigation.register(config)`
 * inside its own `module.config.js`. This central loader iterates through the
 * array of all 14 module IDs and dynamically loads their configuration files
 * sequentially before the navigation shell renders.
 */

(function () {
  // Master list of all 14 project-to-cash module IDs
  const MODULE_IDS = [
    "overview",
    "access",
    "commercial",
    "projects",
    "delivery",
    "risk",
    "acceptance",
    "project-to-cash",
    "billing",
    "invoices",
    "collections",
    "payments",
    "working-capital",
    "liquidity"
  ];

  // Defensive early registration stub in case module configs load before navigation.js
  window.FinnovaNavigation = window.FinnovaNavigation || {
    _queue: [],
    register: function (config) {
      if (this._queue) {
        this._queue.push(config);
      }
    }
  };

  function loadScript(src) {
    return new Promise((resolve) => {
      const script = document.createElement("script");
      script.src = src;
      script.onload = () => resolve();
      script.onerror = (err) => {
        console.warn(`[Finnova Registry] Could not load module config from "${src}":`, err);
        resolve(); // Continue chain even if one module fails
      };
      document.head.appendChild(script);
    });
  }

  let loadPromise = null;

  function loadAll() {
    if (loadPromise) return loadPromise;

    loadPromise = MODULE_IDS.reduce((promise, id) => {
      return promise.then(() => loadScript(`modules/${id}/module.config.js`));
    }, Promise.resolve());

    return loadPromise;
  }

  window.FinnovaModuleRegistry = {
    modules: MODULE_IDS,
    loadAll: loadAll,
    get ready() {
      return loadAll();
    }
  };

  // Start sequential loading immediately
  loadAll();
})();
